mapper.select:
SELECT b.user_name as userName, b.user_id as userId, b.avatar, a.visit_time as visitTime, a.visit_source as visitSource, a.card_id as cardId, bc.card_id as inviteeCardId, (select count(*) from user_card_list ucl where ucl.card_id=bc.card_id and ucl.user_id=#{userId}) as userCardListCount, (select m.status from message_info m where m.by_user_id=#{userId} and m.platform_id=bc.card_id and m.type=1 and m.state=6) as messageStatus FROM `visit_card_record` a LEFT JOIN tb_user b ON a.user_id = b.user_id left join business_card bc on bc.user_id=b.user_id AND bc.audit_status = 1 AND bc.card_status = 1 where 1=1 and b.user_id is not null
and a.card_id=#{cardId}
GROUP BY userId order by a.visit_time desc limit 3
